#!/usr/bin/env python3
"""Cron wake gate for this Hermes profile (728-D plan D3; 728-EF D10).

GENERATED by generator/generate.py from generator/data/gate.py.tmpl and
the role's `gate_wake_kinds` in generator/data/role-configs.json — do
not edit the rendered copy under dist/.

Hermes runs this script before a cron tick. The LAST stdout line decides:
`{"wakeAgent": false}` skips the model run entirely; anything else —
including this script failing — wakes the profile (the safe direction).
So on ANY error this script exits non-zero and prints NO wakeAgent line.

Logic: home = the parent of the scripts/ directory containing this file;
role = the home directory's name. The role's bearer token is read from
<home>/.env (`MCP_SERVICE_TOKEN_<ROLE>`). One unfiltered
`artifacts_list(unprocessed_for=<role>, limit=500)` call is made to the
in-cluster personal-mcp server (initialize handshake first, mirroring
the proven 728-H bridge clients in custom.personal-mcp*), and the result
is type-filtered client-side (the D10 fallback shape): wake iff any
returned item's kind (`type` in the store's index entries) is in
WAKE_KINDS below.
"""

from __future__ import annotations

import json
import sys
import urllib.error
import urllib.request
from pathlib import Path

# Per-role constants (rendered from role-configs.json `gate_wake_kinds`).
WAKE_KINDS = frozenset(["receipt", "report", "consult-response"])

PERSONAL_MCP_URL = "http://personal-mcp.personal-mcp.svc.cluster.local:80/mcp"
PROTOCOLS = {"2025-11-25", "2025-06-18", "2025-03-26"}
TIMEOUT_SECONDS = 30


class GateError(RuntimeError):
    """Any failure: exit non-zero, no wakeAgent line (Hermes wakes)."""


def load_token(home: Path, role: str) -> str:
    var = f"MCP_SERVICE_TOKEN_{role.upper()}"
    env_path = home / ".env"
    try:
        lines = env_path.read_text(encoding="utf-8").splitlines()
    except OSError as exc:
        raise GateError(f"cannot read {env_path}: {exc}") from None
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("export "):
            line = line[len("export "):].lstrip()
        key, sep, value = line.partition("=")
        if not sep or key.strip() != var:
            continue
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
            value = value[1:-1]
        if value:
            return value
        break
    raise GateError(f"{var} missing or empty in {env_path}")


class McpClient:
    """Minimal streamable-HTTP MCP client (stdlib only).

    Request/response shape mirrors the proven 728-H bridge clients:
    initialize handshake, notifications/initialized, Mcp-Session-Id
    capture/replay, JSON or text/event-stream response envelopes.
    """

    def __init__(self, token: str) -> None:
        self.token = token
        self.opener = urllib.request.build_opener()
        self.session: str | None = None
        self.protocol = "2025-11-25"
        self.sequence = 0

    def send(self, method: str, params: dict, *, notification: bool = False):
        self.sequence += 1
        request_id = None if notification else self.sequence
        body: dict = {"jsonrpc": "2.0", "method": method, "params": params}
        if request_id is not None:
            body["id"] = request_id
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json, text/event-stream",
            "MCP-Protocol-Version": self.protocol,
            "Authorization": f"Bearer {self.token}",
            # An explicit non-urllib UA (the bridge clients require one
            # at the Cloudflare edge; harmless in-cluster).
            "User-Agent": "gb-gate/1.0",
        }
        if self.session:
            headers["Mcp-Session-Id"] = self.session
        request = urllib.request.Request(
            PERSONAL_MCP_URL, data=json.dumps(body).encode(), headers=headers, method="POST"
        )
        try:
            with self.opener.open(request, timeout=TIMEOUT_SECONDS) as response:
                if session := response.headers.get("Mcp-Session-Id"):
                    if not all(33 <= ord(c) <= 126 for c in session):
                        raise GateError("MCP server returned an invalid session header")
                    self.session = session
                if notification:
                    if response.status == 202:
                        return None
                    raise GateError("MCP server did not accept the initialization notification")
                return self.read_result(response, request_id)
        except urllib.error.HTTPError as error:
            raise GateError(f"MCP returned HTTP {error.code}") from None
        except (urllib.error.URLError, TimeoutError, OSError) as exc:
            raise GateError(f"MCP request did not complete: {exc}") from None

    @staticmethod
    def decode(payload: bytes, request_id: int):
        message = json.loads(payload)
        if not isinstance(message, dict) or message.get("jsonrpc") != "2.0":
            raise GateError("MCP returned an invalid JSON-RPC message")
        if type(message.get("id")) is not int or message["id"] != request_id:
            return None
        if "error" in message:
            raise GateError("MCP returned a JSON-RPC error")
        if not isinstance(message.get("result"), dict):
            raise GateError("MCP returned no result object")
        return message["result"]

    @classmethod
    def read_result(cls, response, request_id: int):
        content_type = response.headers.get_content_type()
        if content_type == "application/json":
            result = cls.decode(response.read(), request_id)
            if result is None:
                raise GateError("MCP returned the wrong request ID")
            return result
        if content_type != "text/event-stream":
            raise GateError("MCP returned an unsupported content type")
        data: list[bytes] = []
        while True:
            line = response.readline()
            if not line:
                raise GateError("MCP event stream ended before the matching result")
            line = line.rstrip(b"\r\n")
            if line.startswith(b"data:"):
                data.append(line[5:].lstrip(b" "))
            elif not line and data:
                result = cls.decode(b"\n".join(data), request_id)
                data.clear()
                if result is not None:
                    return result

    def initialize(self) -> None:
        result = self.send("initialize", {
            "protocolVersion": self.protocol,
            "capabilities": {},
            "clientInfo": {"name": "gb-gate", "version": "1"},
        })
        protocol = result.get("protocolVersion")
        capabilities = result.get("capabilities")
        if (
            not isinstance(protocol, str)
            or protocol not in PROTOCOLS
            or not isinstance(capabilities, dict)
            or not isinstance(capabilities.get("tools"), dict)
        ):
            raise GateError("MCP server did not negotiate a supported tool protocol")
        self.protocol = protocol
        self.send("notifications/initialized", {}, notification=True)

    def call_tool(self, name: str, arguments: dict) -> dict:
        result = self.send("tools/call", {"name": name, "arguments": arguments})
        if result.get("isError"):
            raise GateError(f"MCP tool {name} returned isError")
        return result


def extract_items(result: dict) -> list:
    """Unwrap a tools/call result to the artifacts_list payload's items.

    FastMCP returns the tool's dict as `structuredContent` plus a text
    block in `content`; accept either, or a bare result dict.
    """
    payload = None
    structured = result.get("structuredContent")
    if isinstance(structured, dict):
        payload = structured
    if payload is None or "artifacts" not in payload:
        for block in result.get("content") or []:
            if isinstance(block, dict) and block.get("type") == "text":
                try:
                    parsed = json.loads(block.get("text") or "")
                except ValueError:
                    continue
                if isinstance(parsed, dict):
                    payload = parsed
                    break
    if payload is None and "artifacts" in result:
        payload = result
    if not isinstance(payload, dict) or not isinstance(payload.get("artifacts"), list):
        raise GateError("artifacts_list result carries no artifacts list")
    return payload["artifacts"]


def main() -> int:
    home = Path(__file__).resolve().parent.parent
    role = home.name
    if not role:
        raise GateError("cannot derive role from script location")
    token = load_token(home, role)
    client = McpClient(token)
    client.initialize()
    result = client.call_tool(
        "artifacts_list", {"unprocessed_for": role, "limit": 500}
    )
    items = extract_items(result)
    wake = any(
        isinstance(item, dict) and (item.get("kind") or item.get("type")) in WAKE_KINDS
        for item in items
    )
    print(json.dumps({"wakeAgent": wake}))
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as error:  # any failure wakes (safe direction)
        print(f"gate error: {error}", file=sys.stderr)
        raise SystemExit(1)
